# Lighting math: efficacy + inverse square (public-domain formulas)
SOURCES = {"candle": 0.1, "oil lamp": 0.2, "gas mantle": 1.5, "carbon arc": 15,
           "incandescent 1910": 4, "tungsten 1930": 12, "fluorescent": 60,
           "sodium vapor": 120}
for name, eff in SOURCES.items():
    watts_for_800lm = 800 / eff
    print(f"{name:18s}: {eff:6.1f} lm/W  ->  800 lm needs {watts_for_800lm:7.0f} W")

def illuminance_lux(lumens, distance_m):
    return lumens / (4 * 3.14159 * distance_m**2)
print(f"\n1000-lm gas mantle at 3m: {illuminance_lux(1000, 3):.1f} lux "
      f"(office needs ~500; hence many lamps)")
